import os,subprocess,pathlib,json
home=pathlib.Path.home()
out={"home":str(home),"path":os.environ.get("PATH",""),"files":{},"commands":{},"processes":""}
for n in [".bashrc",".profile",".bash_profile",".bash_login",".zshrc"]:
 p=home/n
 if p.exists():
  try: out["files"][n]=p.read_text(errors="replace")[-12000:]
  except Exception as e: out["files"][n]="ERR:"+repr(e)
for cmd in [["bash","--noprofile","--norc","-c","echo CLEAN_SHELL_OK; command -v node || true; command -v npm || true; command -v npx || true"],
            ["timeout","4","bash","-lc","echo LOGIN_SHELL_OK"],
            ["timeout","4","node","-v"],
            ["timeout","4","npm","-v"],
            ["timeout","4","npx","--version"]]:
 try:
  q=subprocess.run(cmd,text=True,capture_output=True,timeout=8)
  out["commands"][" ".join(cmd)]={"rc":q.returncode,"stdout":q.stdout[-4000:],"stderr":q.stderr[-4000:]}
 except Exception as e: out["commands"][" ".join(cmd)]={"error":repr(e)}
try:
 q=subprocess.run(["ps","-eo","pid,ppid,user,stat,etime,args"],text=True,capture_output=True,timeout=5)
 out["processes"]="\n".join([ln for ln in q.stdout.splitlines() if any(k in ln.lower() for k in ["node","npm","npx","onchain","black","bash"])])[-12000:]
except Exception as e: out["processes"]="ERR:"+repr(e)
print(json.dumps(out,indent=2))
